/* Verse Games: THE WHOLE COUNSEL · Deuteronomy chapters 16-20
   Verse text is filled/verified from the KJV by tools/fill-verses.js */
VG.registerBibleChapters("deuteronomy", [
{n:16, name:"The Three Feasts", seal:{ref:"Deuteronomy 16:17",verse:"Every man shall give as he is able, according to the blessing of the LORD thy God which he hath given thee."}, facts:["Did you know the Passover was kept in Abib, the very month Israel left Egypt 'by night,' so the feast forever remembered the night of deliverance (Deuteronomy 16:1)?","Did you know the three great feasts required every Israelite male to appear 'before the LORD thy God,' making worship a journey and not just a routine (Deuteronomy 16:16)?","Did you know the same chapter that commands the feasts also forbids judges to take gifts, 'for a gift doth blind the eyes of the wise' (Deuteronomy 16:19)?"], questions:[
{q:"In which month was Israel to observe the Passover?", options:["Abib","Zif","Bul","Ethanim"], a:0, ref:"Deuteronomy 16:1",verse:"Observe the month of Abib, and keep the passover unto the LORD thy God: for in the month of Abib the LORD thy God brought thee forth out of Egypt by night.", insight:"Abib was the month of new beginnings; God ties worship to the calendar of His rescue."},
{q:"Why was the Passover kept in the month of Abib?", options:["The LORD brought Israel out of Egypt by night in that month","It was the month of the harvest","Moses was born in that month","The manna first fell then"], a:0, ref:"Deuteronomy 16:1",verse:"Observe the month of Abib, and keep the passover unto the LORD thy God: for in the month of Abib the LORD thy God brought thee forth out of Egypt by night.", insight:"'By night' God moved; remember the dark hours when He acted for you."},
{q:"Where was the Passover sacrifice to be offered?", options:["In the place which the LORD thy God shall choose","Within any of their gates","At the family tent","On the highest hill"], a:0, ref:"Deuteronomy 16:2",verse:"Thou shalt therefore sacrifice the passover unto the LORD thy God, of the flock and the herd, in the place which the LORD shall choose to place his name there.", insight:"God chooses the place of worship; we do not set the terms of meeting Him."},
{q:"For how many days was unleavened bread to be eaten at Passover?", options:["Seven days","Three days","Forty days","One day"], a:0, ref:"Deuteronomy 16:3",verse:"Thou shalt eat no leavened bread with it; seven days shalt thou eat unleavened bread therewith, even the bread of affliction; for thou camest forth out of the land of Egypt in haste: that thou mayest remember the day when thou camest forth out of the land of Egypt all the days of thy life.", insight:"Seven days of unleavened bread; holiness is not a moment but a habit."},
{q:"What was the unleavened bread called, and why?", options:["The bread of affliction, because they came out of Egypt in haste","The bread of heaven, because it fell from the sky","The bread of peace, because the war had ended","The bread of firstfruits, because of the harvest"], a:0, ref:"Deuteronomy 16:3",verse:"Thou shalt eat no leavened bread with it; seven days shalt thou eat unleavened bread therewith, even the bread of affliction; for thou camest forth out of the land of Egypt in haste: that thou mayest remember the day when thou camest forth out of the land of Egypt all the days of thy life.", insight:"The bread of affliction; God has them taste the hurry of deliverance every year."},
{q:"How long was no leaven to be seen in all Israel's coasts?", options:["Seven days","Until the new moon","Three days","Forty days"], a:0, ref:"Deuteronomy 16:4",verse:"And there shall be no leavened bread seen with thee in all thy coast seven days; neither shall there any thing of the flesh, which thou sacrificedst the first day at even, remain all night until the morning.", insight:"No leaven in all their coasts; a little sin leavens the whole life."},
{q:"At what time of day was the Passover sacrificed?", options:["At even, at the going down of the sun","At sunrise","At noon","At midnight"], a:0, ref:"Deuteronomy 16:6",verse:"But at the place which the LORD thy God shall choose to place his name in, there thou shalt sacrifice the passover at even, at the going down of the sun, at the season that thou camest forth out of Egypt.", insight:"At the going down of the sun; deliverance came at evening, and Christ our Passover died at evening too."},
{q:"What was the worshipper to do in the morning after the Passover?", options:["Turn, and go unto his tents","Stay seven more days","Offer a second lamb","Travel to Jerusalem"], a:0, ref:"Deuteronomy 16:7",verse:"And thou shalt roast and eat it in the place which the LORD thy God shall choose: and thou shalt turn in the morning, and go unto thy tents.", insight:"Feast, then return home; worship sends you back to ordinary life renewed."},
{q:"What marked the seventh day of the feast?", options:["A solemn assembly, with no work done","A second sacrifice of a lamb","A journey to the Jordan","A fast until evening"], a:0, ref:"Deuteronomy 16:8",verse:"Six days thou shalt eat unleavened bread: and on the seventh day shall be a solemn assembly to the LORD thy God: thou shalt do no work therein.", insight:"The feast ends in solemn assembly; joy and reverence belong together."},
{q:"When did the counting of the seven weeks begin?", options:["When thou beginnest to put the sickle to the corn","At the new moon of spring","When the first lamb was born","After the rains ended"], a:0, ref:"Deuteronomy 16:9",verse:"Seven weeks shalt thou number unto thee: begin to number the seven weeks from such time as thou beginnest to put the sickle to the corn.", insight:"Count from the first cut of the sickle; gratitude starts when the harvest starts."},
{q:"What offering belonged to the feast of weeks?", options:["A tribute of a freewill offering, as the LORD had blessed","A fixed tax of silver","A burnt offering of doves only","The firstborn of the flock"], a:0, ref:"Deuteronomy 16:10",verse:"And thou shalt keep the feast of weeks unto the LORD thy God with a tribute of a freewill offering of thine hand, which thou shalt give unto the LORD thy God, according as the LORD thy God hath blessed thee:", insight:"A freewill offering measured by blessing; give as God has given to you."},
{q:"Whom was the rejoicing household to include?", options:["The Levite, the stranger, the fatherless, and the widow","Only the priests and elders","The king and his servants","The merchants of the city"], a:0, ref:"Deuteronomy 16:11",verse:"And thou shalt rejoice before the LORD thy God, thou, and thy son, and thy daughter, and thy manservant, and thy maidservant, and the Levite that is within thy gates, and the stranger, and the fatherless, and the widow, that are among you, in the place which the LORD thy God hath chosen to place his name there.", insight:"Joy that leaves out the stranger and the widow is not God's joy."},
{q:"What was Israel to remember at the feasts?", options:["That thou wast a bondman in Egypt","That thou wast a great nation","That the sea parted for thee","That manna fell for thee"], a:0, ref:"Deuteronomy 16:12",verse:"And thou shalt remember that thou wast a bondman in Egypt: and thou shalt observe and do these statutes.", insight:"Remember you were a bondman; memory of mercy keeps celebration humble."},
{q:"When was the feast of tabernacles kept?", options:["After thou hast gathered in thy corn and thy wine","Before the spring rains","At the first new moon","When the flocks were shorn"], a:0, ref:"Deuteronomy 16:13",verse:"Thou shalt observe the feast of tabernacles seven days, after that thou hast gathered in thy corn and thy wine:", insight:"Celebrate after the gathering; thank God when the barns are full, not only when they are empty."},
{q:"Why was Israel to rejoice in the feast?", options:["Because the LORD would bless them in all their increase and works","Because their enemies were defeated","Because the king commanded it","Because the harvest was the largest ever"], a:0, ref:"Deuteronomy 16:15",verse:"Seven days shalt thou keep a solemn feast unto the LORD thy God in the place which the LORD shall choose: because the LORD thy God shall bless thee in all thine increase, and in all the works of thine hands, therefore thou shalt surely rejoice.", insight:"'The LORD thy God shall bless thee'; rejoicing is the echo of blessing."},
{q:"How many times a year were all the males to appear before the LORD?", options:["Three times","Seven times","Twelve times","Once"], a:0, ref:"Deuteronomy 16:16",verse:"Three times in a year shall all thy males appear before the LORD thy God in the place which he shall choose; in the feast of unleavened bread, and in the feast of weeks, and in the feast of tabernacles: and they shall not appear before the LORD empty:", insight:"Three pilgrimages a year; God built travel into worship so faith never grew stale at home."},
{q:"Which three feasts required the pilgrimage?", options:["Unleavened bread, weeks, and tabernacles","Passover, trumpets, and atonement","Weeks, harvest, and new moon","Tabernacles, dedication, and Purim"], a:0, ref:"Deuteronomy 16:16",verse:"Three times in a year shall all thy males appear before the LORD thy God in the place which he shall choose; in the feast of unleavened bread, and in the feast of weeks, and in the feast of tabernacles: and they shall not appear before the LORD empty:", insight:"Unleavened bread, weeks, tabernacles; each feast rehearsed a chapter of God's saving story."},
{q:"How much was every man to give when he appeared?", options:["As he is able, according to the blessing of the LORD","A tenth of all his goods","One silver shekel","Whatever the priest demanded"], a:0, ref:"Deuteronomy 16:17",verse:"Every man shall give as he is able, according to the blessing of the LORD thy God which he hath given thee.", insight:"As he is able; God measures the gift by the giver's blessing, not by another man's purse."},
{q:"Where were judges and officers to be appointed?", options:["In all thy gates","Only in Jerusalem","At the temple steps","In every synagogue"], a:0, ref:"Deuteronomy 16:18",verse:"Judges and officers shalt thou make thee in all thy gates, which the LORD thy God giveth thee, throughout thy tribes: and they shall judge the people with just judgment.", insight:"Justice in all thy gates; righteousness must reach the local and the ordinary."},
{q:"What did the LORD hate, that Israel must not set up?", options:["Any image","A second altar","A bronze serpent","A memorial stone"], a:0, ref:"Deuteronomy 16:22",verse:"Neither shalt thou set thee up any image; which the LORD thy God hateth.", insight:"God hates rival images; He will not share the worship of His people."}
]},
{n:17, name:"The Law of the King", seal:{ref:"Deuteronomy 17:20",verse:"That his heart be not lifted up above his brethren, and that he turn not aside from the commandment, to the right hand, or to the left: to the end that he may prolong his days in his kingdom, he, and his children, in the midst of Israel."}, facts:["Did you know a capital case in Israel required two or three witnesses, and the witnesses had to cast the first stone, so no one could accuse lightly (Deuteronomy 17:6-7)?","Did you know Israel's king was commanded to handwrite his own copy of the law and read it every day of his life, a king ruled by the Book (Deuteronomy 17:18-19)?","Did you know the king was forbidden to multiply horses because horses meant going back to Egypt for them, a return to the old bondage (Deuteronomy 17:16)?"], questions:[
{q:"What kind of animal must not be sacrificed to the LORD?", options:["A bullock or sheep with blemish or any evil favouredness","A lamb under a year old","An ox from another tribe","A goat without horns"], a:0, ref:"Deuteronomy 17:1",verse:"Thou shalt not sacrifice unto the LORD thy God any bullock, or sheep, wherein is blemish, or any evilfavouredness: for that is an abomination unto the LORD thy God.", insight:"No blemished sacrifice; God deserves the best of the flock, not the leftovers."},
{q:"What wickedness called for judgment in Israel?", options:["Serving other gods, and worshipping the sun, the moon, or the host of heaven","Eating leavened bread","Working on the Sabbath","Borrowing from a stranger"], a:0, ref:"Deuteronomy 17:3",verse:"And hath gone and served other gods, and worshipped them, either the sun, or moon, or any of the host of heaven, which I have not commanded;", insight:"Idolatry broke the covenant at its root; worship decides everything else."},
{q:"What was required before anyone was condemned?", options:["Diligent inquiry, until the thing was true and certain","The word of a single witness","The anger of the people","A sign from heaven"], a:0, ref:"Deuteronomy 17:4",verse:"And it be told thee, and thou hast heard of it, and enquired diligently, and, behold, it be true, and the thing certain, that such abomination is wrought in Israel:", insight:"Inquire diligently; justice hurries slowly, and certainty comes before sentence."},
{q:"Where was the idolater to be brought for punishment?", options:["Unto thy gates, and stoned with stones","To the wilderness","Before the king's palace","Outside the camp only"], a:0, ref:"Deuteronomy 17:5",verse:"Then shalt thou bring forth that man or that woman, which have committed that wicked thing, unto thy gates, even that man or that woman, and shalt stone them with stones, till they die.", insight:"At the gates, where all could see; hidden sin answered in the open deters hidden sin."},
{q:"On whose testimony could a man be put to death?", options:["Two or three witnesses, never one alone","A single witness","The priest alone","Ten elders"], a:0, ref:"Deuteronomy 17:6",verse:"At the mouth of two witnesses, or three witnesses, shall he that is worthy of death be put to death; but at the mouth of one witness he shall not be put to death.", insight:"Not at the mouth of one witness; God protects the accused from a lone accuser."},
{q:"Whose hand was to be first upon the condemned?", options:["The hand of the witnesses","The hand of the priest","The hand of the king","The hand of the avenger"], a:0, ref:"Deuteronomy 17:7",verse:"The hands of the witnesses shall be first upon him to put him to death, and afterward the hands of all the people. So thou shalt put the evil away from among you.", insight:"The witnesses cast first; accusing costs something, and false charges cost dearly."},
{q:"Why was the punishment carried out publicly?", options:["To put away the evil from among the people","To please the king","To frighten the nations","To honor the witnesses"], a:0, ref:"Deuteronomy 17:7",verse:"The hands of the witnesses shall be first upon him to put him to death, and afterward the hands of all the people. So thou shalt put the evil away from among you.", insight:"Put the evil away; a community that tolerates rot will be rotted by it."},
{q:"Which matters were too hard for the local judges?", options:["Between blood and blood, plea and plea, stroke and stroke","Debts under a shekel","Disputes over lost sheep","Quarrels between brothers"], a:0, ref:"Deuteronomy 17:8",verse:"If there arise a matter too hard for thee in judgment, between blood and blood, between plea and plea, and between stroke and stroke, being matters of controversy within thy gates: then shalt thou arise, and get thee up into the place which the LORD thy God shall choose;", insight:"Blood, plea, and stroke; the hardest cases go up, not away."},
{q:"To whom were the hard cases taken?", options:["The priests the Levites, and the judge of those days","The king alone","The elders of the gate","A prophet"], a:0, ref:"Deuteronomy 17:9",verse:"And thou shalt come unto the priests the Levites, and unto the judge that shall be in those days, and enquire; and they shall shew thee the sentence of judgment:", insight:"Priests and judge together; God joins His word and His order in hard decisions."},
{q:"What was Israel to do with the sentence given?", options:["Do according to all they informed them","Debate it for forty days","Appeal to the king","Follow it only if they agreed"], a:0, ref:"Deuteronomy 17:10",verse:"And thou shalt do according to the sentence, which they of that place which the LORD shall choose shall shew thee; and thou shalt observe to do according to all that they inform thee:", insight:"Do according to the sentence; submission to godly judgment keeps a nation whole."},
{q:"How far might they turn from the sentence?", options:["Neither to the right hand nor to the left","A little to the right","As far as seemed wise","Until a new judge arose"], a:0, ref:"Deuteronomy 17:11",verse:"According to the sentence of the law which they shall teach thee, and according to the judgment which they shall tell thee, thou shalt do: thou shalt not decline from the sentence which they shall shew thee, to the right hand, nor to the left.", insight:"Neither right nor left; obedience has no approved detours."},
{q:"What happened to the man who presumptuously refused priest or judge?", options:["He was put to death","He was exiled for a year","He paid a fine of silver","He was made a servant"], a:0, ref:"Deuteronomy 17:12",verse:"And the man that will do presumptuously, and will not hearken unto the priest that standeth to minister there before the LORD thy God, or unto the judge, even that man shall die: and thou shalt put away the evil from Israel.", insight:"Presumption against God's appointed order was fatal; contempt for judgment spreads like plague."},
{q:"When might Israel set a king over themselves?", options:["When they said, I will set a king over me, like as all the nations","When Moses died","When they entered the land","When the judges failed"], a:0, ref:"Deuteronomy 17:14",verse:"When thou art come unto the land which the LORD thy God giveth thee, and shalt possess it, and shalt dwell therein, and shalt say, I will set a king over me, like as all the nations that are about me;", insight:"'Like as all the nations'; wanting to be like everyone else is a dangerous prayer."},
{q:"Whom must the king be?", options:["One from among thy brethren, never a stranger","The eldest son of the high priest","A mighty warrior from any nation","The richest man in Israel"], a:0, ref:"Deuteronomy 17:15",verse:"Thou shalt in any wise set him king over thee, whom the LORD thy God shall choose: one from among thy brethren shalt thou set king over thee: thou mayest not set a stranger over thee, which is not thy brother.", insight:"From among thy brethren; the king must be one of the people, not above them."},
{q:"Who chose Israel's king?", options:["The LORD thy God","The elders by vote","The priests by lot","The people by acclaim"], a:0, ref:"Deuteronomy 17:15",verse:"Thou shalt in any wise set him king over thee, whom the LORD thy God shall choose: one from among thy brethren shalt thou set king over thee: thou mayest not set a stranger over thee, which is not thy brother.", insight:"'Whom the LORD thy God shall choose'; the crown is God's appointment, not man's ambition."},
{q:"What was the king forbidden to multiply?", options:["Horses, and he must not return the people to Egypt for them","Oxen and sheep","Vineyards and fields","Servants and maids"], a:0, ref:"Deuteronomy 17:16",verse:"But he shall not multiply horses to himself, nor cause the people to return to Egypt, to the end that he should multiply horses: forasmuch as the LORD hath said unto you, Ye shall henceforth return no more that way.", insight:"No return to Egypt; never rebuild the bondage God broke."},
{q:"What else must the king not greatly multiply?", options:["Wives, silver, and gold","Sons and daughters","Cities and towers","Chariots and spears"], a:0, ref:"Deuteronomy 17:17",verse:"Neither shall he multiply wives to himself, that his heart turn not away: neither shall he greatly multiply to himself silver and gold.", insight:"Wives, silver, gold; multiplied desires turn a king's heart away."},
{q:"What was the king to write for himself?", options:["A copy of this law in a book, from that before the priests the Levites","The names of all his servants","A history of the kings of Egypt","New statutes of his own"], a:0, ref:"Deuteronomy 17:18",verse:"And it shall be, when he sitteth upon the throne of his kingdom, that he shall write him a copy of this law in a book out of that which is before the priests the Levites:", insight:"The king handwrites the law; the highest hand in the land copies the highest word."},
{q:"How often was the king to read his copy?", options:["All the days of his life, to learn to fear the LORD","Once a year at the feast","Every Sabbath only","When going to war"], a:0, ref:"Deuteronomy 17:19",verse:"And it shall be with him, and he shall read therein all the days of his life: that he may learn to fear the LORD his God, to keep all the words of this law and these statutes, to do them:", insight:"Read all his days; a king who stops learning the law stops fearing the Lord."},
{q:"What would daily reading keep the king from?", options:["Lifting his heart above his brethren, and turning aside right or left","Growing old","Losing battles","Paying tribute"], a:0, ref:"Deuteronomy 17:20",verse:"That his heart be not lifted up above his brethren, and that he turn not aside from the commandment, to the right hand, or to the left: to the end that he may prolong his days in his kingdom, he, and his children, in the midst of Israel.", insight:"Not lifted up, not turned aside; the Book keeps kings humble and straight."}
]},
{n:18, name:"The Prophet Like Moses", seal:{ref:"Deuteronomy 18:18",verse:"I will raise them up a Prophet from among their brethren, like unto thee, and will put my words in his mouth; and he shall speak unto them all that I shall command him."}, facts:["Did you know Moses promised that God would raise up a Prophet 'like unto me,' a promise the apostle Peter later applied directly to Jesus Christ (Deuteronomy 18:15)?","Did you know the Levites' portion was not land but the LORD Himself: 'the LORD is their inheritance' (Deuteronomy 18:2)?","Did you know the law listed nine forbidden occult practices, from passing children through fire to consulting the dead, all called abomination to the LORD (Deuteronomy 18:10-12)?"], questions:[
{q:"What portion did the priests, the tribe of Levi, receive?", options:["No part nor inheritance with Israel; they ate the offerings made by fire","The best farmland in Canaan","A double share of the spoil","The cities of the Levites only"], a:0, ref:"Deuteronomy 18:1",verse:"The priests the Levites, and all the tribe of Levi, shall have no part nor inheritance with Israel: they shall eat the offerings of the LORD made by fire, and his inheritance.", insight:"No land, but the altar's portion; God Himself was their estate."},
{q:"Who was the inheritance of the Levites?", options:["The LORD","The high priest","The tabernacle","The people of Israel"], a:0, ref:"Deuteronomy 18:2",verse:"Therefore shall they have no inheritance among their brethren: the LORD is their inheritance, as he hath said unto them.", insight:"'The LORD is their inheritance'; some are rich in land, and some are rich in God."},
{q:"What was the priest's due from an ox or sheep sacrificed?", options:["The shoulder, the two cheeks, and the maw","The loins and the fat","The head and the feet","The blood and the skin"], a:0, ref:"Deuteronomy 18:3",verse:"And this shall be the priest’s due from the people, from them that offer a sacrifice, whether it be ox or sheep; and they shall give unto the priest the shoulder, and the two cheeks, and the maw.", insight:"Shoulder, cheeks, maw; God feeds His servants from the worship of His people."},
{q:"Of what firstfruits was the priest to receive a share?", options:["Corn, wine, oil, and the fleece of the sheep","Gold, silver, and jewels","Honey and spices","Timber and stone"], a:0, ref:"Deuteronomy 18:4",verse:"The firstfruit also of thy corn, of thy wine, and of thine oil, and the first of the fleece of thy sheep, shalt thou give him.", insight:"Firstfruits, not leftovers; those who serve God eat first from the harvest."},
{q:"For what had the LORD chosen the Levite?", options:["To stand to minister in the name of the LORD for ever","To rule over the tribes","To fight in the vanguard","To keep the treasury"], a:0, ref:"Deuteronomy 18:5",verse:"For the LORD thy God hath chosen him out of all thy tribes, to stand to minister in the name of the LORD, him and his sons for ever.", insight:"Chosen to stand and minister; the highest calling is simply to stand before God for others."},
{q:"If a Levite came from any gate to the chosen place, what might he do?", options:["Minister in the name of the LORD like his brethren","Offer sacrifices only at home","Teach but never minister","Serve only as a doorkeeper"], a:0, ref:"Deuteronomy 18:6",verse:"And if a Levite come from any of thy gates out of all Israel, where he sojourned, and come with all the desire of his mind unto the place which the LORD shall choose;", insight:"From any gate he might come; desire for God's house is itself a calling."},
{q:"What share did the visiting Levite receive?", options:["Like portions to eat with his brethren","Half portions","Only what was left over","Nothing, since he was a guest"], a:0, ref:"Deuteronomy 18:8",verse:"They shall have like portions to eat, beside that which cometh of the sale of his patrimony.", insight:"Like portions; God does not grade His servants' portions by their address."},
{q:"What were the Israelites forbidden to learn?", options:["The abominations of the nations of the land","The languages of the nations","The crafts of the nations","The songs of the nations"], a:0, ref:"Deuteronomy 18:9",verse:"When thou art come into the land which the LORD thy God giveth thee, thou shalt not learn to do after the abominations of those nations.", insight:"Learn not their abominations; some knowledge corrupts the learner."},
{q:"Which of these was forbidden in Israel?", options:["Making a son or daughter to pass through the fire","Offering the firstfruits","Keeping the Sabbath","Circumcising a child"], a:0, ref:"Deuteronomy 18:10",verse:"There shall not be found among you any one that maketh his son or his daughter to pass through the fire, or that useth divination, or an observer of times, or an enchanter, or a witch,", insight:"Children through the fire; the darkest religion always spends its children."},
{q:"Which of these was also forbidden?", options:["A consulter with familiar spirits","A singer of psalms","A keeper of the feast","A builder of altars"], a:0, ref:"Deuteronomy 18:11",verse:"Or a charmer, or a consulter with familiar spirits, or a wizard, or a necromancer.", insight:"Familiar spirits are strangers to God; seek the living, not the dead."},
{q:"Why were the nations driven out before Israel?", options:["Because they did these abominations","Because they were wealthy","Because they were few","Because they refused tribute"], a:0, ref:"Deuteronomy 18:12",verse:"For all that do these things are an abomination unto the LORD: and because of these abominations the LORD thy God doth drive them out from before thee.", insight:"The land vomited them out for these very sins; judgment on Canaan warns Israel."},
{q:"What was Israel commanded to be with the LORD?", options:["Perfect","Mighty","Rich","Feared"], a:0, ref:"Deuteronomy 18:13",verse:"Thou shalt be perfect with the LORD thy God.", insight:"'Thou shalt be perfect'; wholehearted, not flawless, is what God asks."},
{q:"To whom did the nations hearken?", options:["Observers of times, and diviners","Wise kings","Aged counselors","Mighty warriors"], a:0, ref:"Deuteronomy 18:14",verse:"For these nations, which thou shalt possess, hearkened unto observers of times, and unto diviners: but as for thee, the LORD thy God hath not suffered thee so to do.", insight:"The nations hearkened to diviners; God's people hearken to His word instead."},
{q:"Whom would the LORD raise up for Israel?", options:["A Prophet from the midst of thee, of thy brethren, like unto Moses","A king from Egypt","A priest from Aaron only","An angel from heaven"], a:0, ref:"Deuteronomy 18:15",verse:"The LORD thy God will raise up unto thee a Prophet from the midst of thee, of thy brethren, like unto me; unto him ye shall hearken;", insight:"A Prophet like Moses; God never leaves His people without His voice."},
{q:"What was Israel to do with that Prophet?", options:["Hearken unto him","Test him for forty days","Crown him king","Build him a house"], a:0, ref:"Deuteronomy 18:15",verse:"The LORD thy God will raise up unto thee a Prophet from the midst of thee, of thy brethren, like unto me; unto him ye shall hearken;", insight:"'Unto him ye shall hearken'; when God speaks, listening is obedience."},
{q:"What had Israel asked at Horeb?", options:["Let me not hear the voice of the LORD nor see this great fire, lest I die","Give us a king to judge us","Let us return to Egypt","Show us the promised land"], a:0, ref:"Deuteronomy 18:16",verse:"According to all that thou desiredst of the LORD thy God in Horeb in the day of the assembly, saying, Let me not hear again the voice of the LORD my God, neither let me see this great fire any more, that I die not.", insight:"They feared the fire and the voice; so God promised a Prophet with a human voice."},
{q:"What would God put in the Prophet's mouth?", options:["His words, and he shall speak all that He commands","Parables and riddles","The laws of the nations","Songs of deliverance"], a:0, ref:"Deuteronomy 18:18",verse:"I will raise them up a Prophet from among their brethren, like unto thee, and will put my words in his mouth; and he shall speak unto them all that I shall command him.", insight:"'I will put my words in his mouth'; true prophets speak God's words, not their own."},
{q:"What would happen to whoever would not hearken to the Prophet?", options:["The LORD would require it of him","He would be exiled","He would pay double","Nothing would happen"], a:0, ref:"Deuteronomy 18:19",verse:"And it shall come to pass, that whosoever will not hearken unto my words which he shall speak in my name, I will require it of him.", insight:"God will require it; ignoring His voice is never a neutral act."},
{q:"Which prophet was to be put to death?", options:["He who presumed to speak a word God had not commanded, or spoke in the name of other gods","He whose prophecy was unpopular","He who prophesied only of judgment","He who came from another tribe"], a:0, ref:"Deuteronomy 18:20",verse:"But the prophet, which shall presume to speak a word in my name, which I have not commanded him to speak, or that shall speak in the name of other gods, even that prophet shall die.", insight:"Presumption in God's name is deadly serious; never claim 'the LORD says' lightly."},
{q:"How could Israel know a word the LORD had not spoken?", options:["If the thing follow not, nor come to pass","If it sounded harsh","If the prophet was poor","If it came at night"], a:0, ref:"Deuteronomy 18:22",verse:"When a prophet speaketh in the name of the LORD, if the thing follow not, nor come to pass, that is the thing which the LORD hath not spoken, but the prophet hath spoken it presumptuously: thou shalt not be afraid of him.", insight:"Fulfillment is the test; time exposes what excitement hides."}
]},
{n:19, name:"Cities of Refuge", seal:{ref:"Deuteronomy 19:10",verse:"That innocent blood be not shed in thy land, which the LORD thy God giveth thee for an inheritance, and so blood be upon thee."}, facts:["Did you know the cities of refuge were a picture of Christ: the guilty could run to them and live, as sinners run to Him (Deuteronomy 19:4-5)?","Did you know Israel had to build and maintain good roads to the cities of refuge, so that 'every slayer may flee thither' without hindrance (Deuteronomy 19:3)?","Did you know a single witness could never convict in Israel; 'at the mouth of two witnesses, or at the mouth of three witnesses, shall the matter be established' (Deuteronomy 19:15)?"], questions:[
{q:"How many cities of refuge was Israel to separate?", options:["Three","Six","Seven","Twelve"], a:0, ref:"Deuteronomy 19:2",verse:"Thou shalt separate three cities for thee in the midst of thy land, which the LORD thy God giveth thee to possess it.", insight:"Three cities; God made mercy reachable before judgment was executed."},
{q:"What was Israel to prepare for the slayer?", options:["A way, with the land divided into three parts","A guard of soldiers","A sealed gate","A high wall"], a:0, ref:"Deuteronomy 19:3",verse:"Thou shalt prepare thee a way, and divide the coasts of thy land, which the LORD thy God giveth thee to inherit, into three parts, that every slayer may flee thither.", insight:"Prepare the way; mercy should be easy to reach, not hidden behind obstacles."},
{q:"Who was permitted to flee to the cities?", options:["He who killed his neighbor unawares, whom he hated not in time past","Any murderer","A thief caught at night","A debtor fleeing his creditor"], a:0, ref:"Deuteronomy 19:4",verse:"And this is the case of the slayer, which shall flee thither, that he may live: Whoso killeth his neighbour ignorantly, whom he hated not in time past;", insight:"Unawares, and without hatred; God distinguishes accident from malice."},
{q:"What example of accidental killing is given?", options:["An axe head slipping from the helve in the wood and striking a neighbor","A stone falling from a wall","A fire spreading to a house","An ox goring a stranger"], a:0, ref:"Deuteronomy 19:5",verse:"As when a man goeth into the wood with his neighbour to hew wood, and his hand fetcheth a stroke with the axe to cut down the tree, and the head slippeth from the helve, and lighteth upon his neighbour, that he die; he shall flee unto one of those cities, and live:", insight:"The axe head slips; even ordinary work can turn tragic, and God provides for tragedy."},
{q:"Where was the accidental slayer to flee?", options:["Unto one of those cities, and live","To the tabernacle","Across the Jordan","To the high priest's house"], a:0, ref:"Deuteronomy 19:5",verse:"As when a man goeth into the wood with his neighbour to hew wood, and his hand fetcheth a stroke with the axe to cut down the tree, and the head slippeth from the helve, and lighteth upon his neighbour, that he die; he shall flee unto one of those cities, and live:", insight:"Flee, and live; God gives the guiltless a place to run."},
{q:"Why must the slayer hurry?", options:["Lest the avenger of blood pursue him while his heart is hot","Lest the judges close the gates","Lest night fall","Lest the elders forget"], a:0, ref:"Deuteronomy 19:6",verse:"Lest the avenger of the blood pursue the slayer, while his heart is hot, and overtake him, because the way is long, and slay him; whereas he was not worthy of death, inasmuch as he hated him not in time past.", insight:"While his heart is hot; grief and anger make poor judges, so God gives the accused a head start."},
{q:"When were three more cities to be added?", options:["If the LORD enlarged their coast and they kept His commandments","After forty years","When the population doubled","When a king was crowned"], a:0, ref:"Deuteronomy 19:9",verse:"If thou shalt keep all these commandments to do them, which I command thee this day, to love the LORD thy God, and to walk ever in his ways; then shalt thou add three cities more for thee, beside these three:", insight:"More land, more mercy; blessing widens the reach of grace."},
{q:"Why were the cities appointed?", options:["That innocent blood be not shed in the land","To enrich the Levites","To mark the borders","To shelter the poor"], a:0, ref:"Deuteronomy 19:10",verse:"That innocent blood be not shed in thy land, which the LORD thy God giveth thee for an inheritance, and so blood be upon thee.", insight:"That innocent blood be not shed; God guards the guiltless even from grief-maddened hands."},
{q:"Which killer could not claim refuge?", options:["He who hated his neighbor, lay in wait, and smote him mortally","He who killed in battle","He who struck in sudden anger","He whose axe slipped"], a:0, ref:"Deuteronomy 19:11",verse:"But if any man hate his neighbour, and lie in wait for him, and rise up against him, and smite him mortally that he die, and fleeth into one of these cities:", insight:"Hatred, lying in wait; premeditated murder finds no shelter in God's mercy."},
{q:"What were the elders to do with the deliberate murderer?", options:["Fetch him from the city and deliver him to the avenger of blood","Hide him for a year","Send him to another tribe","Fine him double"], a:0, ref:"Deuteronomy 19:12",verse:"Then the elders of his city shall send and fetch him thence, and deliver him into the hand of the avenger of blood, that he may die.", insight:"Even refuge has limits; mercy never becomes a license for murder."},
{q:"How was Israel to regard the guilty murderer?", options:["Thine eye shall not pity him","With mercy and pardon","With a fine instead","With exile only"], a:0, ref:"Deuteronomy 19:13",verse:"Thine eye shall not pity him, but thou shalt put away the guilt of innocent blood from Israel, that it may go well with thee.", insight:"No pity for the pitiless; justice without sentiment protects the innocent."},
{q:"What ancient boundary must not be moved?", options:["Thy neighbor's landmark, set by them of old time","The city wall","The river Jordan","The king's highway"], a:0, ref:"Deuteronomy 19:14",verse:"Thou shalt not remove thy neighbour’s landmark, which they of old time have set in thine inheritance, which thou shalt inherit in the land that the LORD thy God giveth thee to possess it.", insight:"Move no landmark; quiet theft of a neighbor's ground is theft all the same."},
{q:"Could one witness convict a man?", options:["No; one witness shall not rise up against a man","Yes, if he was a priest","Yes, if he was an elder","Yes, at night"], a:0, ref:"Deuteronomy 19:15",verse:"One witness shall not rise up against a man for any iniquity, or for any sin, in any sin that he sinneth: at the mouth of two witnesses, or at the mouth of three witnesses, shall the matter be established.", insight:"One witness is not enough; God will not hang a man on a single voice."},
{q:"How was any matter established?", options:["At the mouth of two witnesses, or three","By the casting of lots","By the king's decree","By a written confession"], a:0, ref:"Deuteronomy 19:15",verse:"One witness shall not rise up against a man for any iniquity, or for any sin, in any sin that he sinneth: at the mouth of two witnesses, or at the mouth of three witnesses, shall the matter be established.", insight:"Two or three witnesses; truth is confirmed, not assumed."},
{q:"Where did the accuser and accused stand in a false-witness case?", options:["Before the LORD, before the priests and the judges","At the city gate alone","In the king's court","Outside the camp"], a:0, ref:"Deuteronomy 19:17",verse:"Then both the men, between whom the controversy is, shall stand before the LORD, before the priests and the judges, which shall be in those days;", insight:"Before the LORD; every trial is ultimately heard in heaven."},
{q:"What were the judges to make?", options:["Diligent inquisition","A hasty decision","A public spectacle","An offering"], a:0, ref:"Deuteronomy 19:18",verse:"And the judges shall make diligent inquisition: and, behold, if the witness be a false witness, and hath testified falsely against his brother;", insight:"Diligent inquisition; careful judges are God's gift to the accused."},
{q:"What was done to the false witness?", options:["As he thought to have done unto his brother","He was fined a talent","He was whipped","He was exiled"], a:0, ref:"Deuteronomy 19:19",verse:"Then shall ye do unto him, as he had thought to have done unto his brother: so shalt thou put the evil away from among you.", insight:"As he thought to do; the trap he set becomes his own sentence."},
{q:"What effect would this have on the rest?", options:["Those which remain shall hear, and fear, and do no more such evil","They would rebel","They would flee the land","They would mock the judges"], a:0, ref:"Deuteronomy 19:20",verse:"And those which remain shall hear, and fear, and shall henceforth commit no more any such evil among you.", insight:"Hear and fear; just punishment teaches the whole community."},
{q:"What was the measure of justice?", options:["Life for life, eye for eye, tooth for tooth, hand for hand, foot for foot","A fine for every wound","Exile for every crime","Mercy for all"], a:0, ref:"Deuteronomy 19:21",verse:"And thine eye shall not pity; but life shall go for life, eye for eye, tooth for tooth, hand for hand, foot for foot.", insight:"Eye for eye; the punishment fits the crime, never exceeds it."},
{q:"Why was the road to the cities kept open?", options:["That every slayer might flee thither","For the armies to march","For trade with the nations","For the priests to travel"], a:0, ref:"Deuteronomy 19:3",verse:"Thou shalt prepare thee a way, and divide the coasts of thy land, which the LORD thy God giveth thee to inherit, into three parts, that every slayer may flee thither.", insight:"That every slayer may flee; the way of escape must never be blocked."}
]},
{n:20, name:"Laws of Warfare", seal:{ref:"Deuteronomy 20:4",verse:"For the LORD your God is he that goeth with you, to fight for you against your enemies, to save you."}, facts:["Did you know Israel's army sent home four kinds of men before battle: the new homeowner, the new vineyard planter, the newly betrothed, and the fainthearted (Deuteronomy 20:5-8)?","Did you know the priest preached a sermon before every battle: 'let not your hearts faint, fear not,' because the LORD Himself would fight for them (Deuteronomy 20:3-4)?","Did you know Israel was forbidden to cut down fruit trees in a siege, 'for the tree of the field is man's life,' an ancient law of mercy in war (Deuteronomy 20:19)?"], questions:[
{q:"When Israel saw horses, chariots, and more people than themselves, what were they told?", options:["Be not afraid of them","Flee to the mountains","Make a covenant with them","Number their own army"], a:0, ref:"Deuteronomy 20:1",verse:"When thou goest out to battle against thine enemies, and seest horses, and chariots, and a people more than thou, be not afraid of them: for the LORD thy God is with thee, which brought thee up out of the land of Egypt.", insight:"Be not afraid; numbers are not the measure when God is on your side."},
{q:"Why should Israel not fear the greater army?", options:["The LORD thy God is with thee, which brought thee up out of Egypt","They had better weapons","Their enemies were divided","The battle would be short"], a:0, ref:"Deuteronomy 20:1",verse:"When thou goest out to battle against thine enemies, and seest horses, and chariots, and a people more than thou, be not afraid of them: for the LORD thy God is with thee, which brought thee up out of the land of Egypt.", insight:"He brought you out of Egypt; the God of past deliverance is the God of this battle."},
{q:"Who spoke to the army when battle drew near?", options:["The priest","The king","The captain","A prophet"], a:0, ref:"Deuteronomy 20:2",verse:"And it shall be, when ye are come nigh unto the battle, that the priest shall approach and speak unto the people,", insight:"The priest speaks first; before swords, the word of God."},
{q:"What did the priest tell the soldiers?", options:["Let not your hearts faint, fear not, and do not tremble","Charge without mercy","Trust in your chariots","Remember your training"], a:0, ref:"Deuteronomy 20:3",verse:"And shall say unto them, Hear, O Israel, ye approach this day unto battle against your enemies: let not your hearts faint, fear not, and do not tremble, neither be ye terrified because of them;", insight:"Faint not, fear not, tremble not; courage is commanded before it is felt."},
{q:"Why would God go with them?", options:["To fight for them against their enemies, to save them","To punish their sins","To watch their valor","To count their numbers"], a:0, ref:"Deuteronomy 20:4",verse:"For the LORD your God is he that goeth with you, to fight for you against your enemies, to save you.", insight:"To fight for you, to save you; God does not merely cheer His people, He contends for them."},
{q:"In what order were the exemptions given?", options:["New house, new vineyard, betrothed wife, then the fainthearted","Fainthearted first, then the others","Wife, house, vineyard, fainthearted","Vineyard, wife, house, fainthearted"], a:0, ref:"Deuteronomy 20:5",verse:"And the officers shall speak unto the people, saying, What man is there that hath built a new house, and hath not dedicated it? let him go and return to his house, lest he die in the battle, and another man dedicate it.", insight:"House, vineyard, wife, then the fearful; God honors unfinished joys before He drafts soldiers."},
{q:"Who was first sent home from the army?", options:["He that built a new house and had not dedicated it","He that was over forty","He that had no sword","He that was a Levite"], a:0, ref:"Deuteronomy 20:5",verse:"And the officers shall speak unto the people, saying, What man is there that hath built a new house, and hath not dedicated it? let him go and return to his house, lest he die in the battle, and another man dedicate it.", insight:"Dedicate the new house; God lets a man enjoy the work of his hands."},
{q:"Who was next sent home?", options:["He that planted a vineyard and had not yet eaten of it","He that owned many sheep","He that was a merchant","He that had built a wall"], a:0, ref:"Deuteronomy 20:6",verse:"And what man is he that hath planted a vineyard, and hath not yet eaten of it? let him also go and return unto his house, lest he die in the battle, and another man eat of it.", insight:"Eat of thy vineyard; the planter should taste his own fruit."},
{q:"Who was the third to be sent home?", options:["He that had betrothed a wife and had not taken her","He that had many children","He that was newly circumcised","He that was a stranger"], a:0, ref:"Deuteronomy 20:7",verse:"And what man is there that hath betrothed a wife, and hath not taken her? let him go and return unto his house, lest he die in the battle, and another man take her.", insight:"Lest another take her; God guards new love from the waste of war."},
{q:"Who was the last sent home?", options:["He that was fearful and fainthearted","He that was wounded","He that was old","He that was poor"], a:0, ref:"Deuteronomy 20:8",verse:"And the officers shall speak further unto the people, and they shall say, What man is there that is fearful and fainthearted? let him go and return unto his house, lest his brethren’s heart faint as well as his heart.", insight:"The fainthearted go home; fear is contagious, and God quarantines it."},
{q:"If the city made war, what was done?", options:["It was besieged","It was burned at once","Its walls were left alone","Its people were exiled"], a:0, ref:"Deuteronomy 20:12",verse:"And if it will make no peace with thee, but will make war against thee, then thou shalt besiege it:", insight:"Then besiege it; peace refused leaves war as the only road."},
{q:"What was first offered to a city before fighting it?", options:["Peace","Tribute","Surrender of its king","A seven-day wait"], a:0, ref:"Deuteronomy 20:10",verse:"When thou comest nigh unto a city to fight against it, then proclaim peace unto it.", insight:"Proclaim peace first; God opens with mercy even toward enemies."},
{q:"If the city answered with peace and opened, what became of its people?", options:["Tributaries unto Israel, and they shall serve","Free citizens","Exiles","Priests"], a:0, ref:"Deuteronomy 20:11",verse:"And it shall be, if it make thee answer of peace, and open unto thee, then it shall be, that all the people that is found therein shall be tributaries unto thee, and they shall serve thee.", insight:"Tributaries and servants; peace accepted brings life, though under another's yoke."},
{q:"If the city made war, what was done?", options:["It was besieged","It was burned at once","Its walls were left alone","Its people were exiled"], a:0, ref:"Deuteronomy 20:12",verse:"And if it will make no peace with thee, but will make war against thee, then thou shalt besiege it:", insight:"Then besiege it; peace refused leaves war as the only road."},
{q:"When the LORD delivered the city, what happened to the males?", options:["Every male was smitten with the edge of the sword","They were enslaved","They were exiled","They were spared"], a:0, ref:"Deuteronomy 20:13",verse:"And when the LORD thy God hath delivered it into thine hands, thou shalt smite every male thereof with the edge of the sword:", insight:"Solemn and severe; judgment on hardened cities was total."},
{q:"Who was spared, and what was taken?", options:["The women, little ones, and cattle were taken as spoil","All were spared","Nothing was taken","Only the gold was taken"], a:0, ref:"Deuteronomy 20:14",verse:"But the women, and the little ones, and the cattle, and all that is in the city, even all the spoil thereof, shalt thou take unto thyself; and thou shalt eat the spoil of thine enemies, which the LORD thy God hath given thee.", insight:"Women, children, cattle spared; even in judgment, God limits the sword."},
{q:"What was commanded for the cities of the seven nations?", options:["Save alive nothing that breatheth, but utterly destroy them","Take them as tributaries","Drive them out only","Tax them yearly"], a:0, ref:"Deuteronomy 20:16",verse:"But of the cities of these people, which the LORD thy God doth give thee for an inheritance, thou shalt save alive nothing that breatheth:", insight:"Nothing that breathed; the cancer of Canaan's abominations had to be cut out wholly."},
{q:"Why were those nations to be utterly destroyed?", options:["Lest they teach Israel their abominations","Because they were rich","Because they were strong","Because they mocked Israel"], a:0, ref:"Deuteronomy 20:18",verse:"That they teach you not to do after all their abominations, which they have done unto their gods; so should ye sin against the LORD your God.", insight:"Lest they teach you; corrupt worship corrupts the worshipper, so the source was removed."},
{q:"What was forbidden in a long siege?", options:["Destroying the fruit trees with the axe","Building bulwarks","Eating of the trees","Camping near the walls"], a:0, ref:"Deuteronomy 20:19",verse:"When thou shalt besiege a city a long time, in making war against it to take it, thou shalt not destroy the trees thereof by forcing an axe against them: for thou mayest eat of them, and thou shalt not cut them down (for the tree of the field is man’s life) to employ them in the siege:", insight:"Spare the fruit trees; war against men is no war against God's provision."},
{q:"Which trees might be cut down?", options:["Trees which are not trees for meat, to build bulwarks","All the trees","Only the tallest trees","None at all"], a:0, ref:"Deuteronomy 20:20",verse:"Only the trees which thou knowest that they be not trees for meat, thou shalt destroy and cut them down; and thou shalt build bulwarks against the city that maketh war with thee, until it be subdued.", insight:"Only trees not for food; necessity may take timber, but never the orchard."}
]}
]);
